public class Image {public XElement Node;public Image(string name){Node=new XElement(name,new XAttribute("valid","yes"));}public XElement Write()=>new XElement(Node);public static bool Valid(XElement n,string name)=>n!=null&&n.Name==name&&(string)n.Attribute("valid")=="yes";}
