 static RebirthStationRefundArchive Mobile(string job,Guid id,out RebirthCamperStationRefundDeliveryRecord delivery){var a=new RebirthStationGridAdmission(job,true);var q=new RebirthCamperStationPublicationRecord();var i=new RebirthStationTerminalIntent();var r=new RebirthStationCancellationRefund();var t=new RebirthStationCancellationAttempt();var c=new RebirthCamperStationCancellationRecord();Check(RebirthCamperStationRefundDeliveryRecord.TryCreate(id,"owner",a,q,i,r,t,c,new RebirthStationRefundBackpackPlan(),out var prepared)&&prepared.TryMarkAttempted(out _),"mobile destination setup");prepared.TryMarkAttempted(out var attempted);Check(attempted.TryMarkSaved(out delivery),"mobile saved phase setup");Check(RebirthStationRefundArchive.TryCreate("owner",a,q,i,r,t,c,delivery,out var archive),"mobile archive setup");return archive;}
 public static void Run(){var a=new RebirthStationGridAdmission();var q=new RebirthStationPublicationRecord();var i=new RebirthStationTerminalIntent();var r=new RebirthStationCancellationRefund();var t=new RebirthStationCancellationAttempt();var c=new RebirthStationCancellationPublication();var d=new RebirthStationRefundDelivery();Check(RebirthStationRefundArchive.TryCreate("owner",a,q,i,r,t,c,d,out var terrain),"terrain v1 retained");var expected=new XElement("stationRefundArchive",new XAttribute("version",1),new XAttribute("owner","owner"),new XAttribute("job",a.JobId),new XAttribute("creation",a.CreationId),a.Write(),q.Write(),i.Write(),r.Write(),t.Write(),c.Write(),d.Write());Check(terrain.Write().ToString(SaveOptions.DisableFormatting)==expected.ToString(SaveOptions.DisableFormatting)&&!terrain.IsMobile&&terrain.DeliveryId==d.Id,"terrain v1 byte shape and delivery API unchanged");
  var mobile=Mobile("mobile",Guid.NewGuid(),out var delivered);Check(mobile.IsMobile&&mobile.DeliveryId==delivered.DeliveryId&&(string)mobile.Write().Attribute("version")=="2","mobile version and delivery API");Check(RebirthStationRefundArchive.TryRead(mobile.Write(),"owner",out var parsed)&&parsed.IsMobile,"mobile roundtrip");Check(!RebirthStationRefundArchive.TryRead(mobile.Write(),"foreign",out _),"owner conflict denied");
  foreach(var archive in new[]{terrain,mobile}){foreach(var field in new[]{"version","owner","job","creation"}){var bad=archive.Write();bad.SetAttributeValue(field,"wrong");Check(!RebirthStationRefundArchive.TryRead(bad,"owner",out _),"altered archive attribute "+field);}foreach(var child in archive.Write().Elements()){var bad=archive.Write();bad.Element(child.Name).SetAttributeValue("valid","no");Check(!RebirthStationRefundArchive.TryRead(bad,"owner",out _),"altered child "+child.Name);}var extra=archive.Write();extra.Add(new XElement("extra"));Check(!RebirthStationRefundArchive.TryRead(extra,"owner",out _),"extra child denied");extra=archive.Write();extra.Add(new XComment("unexpected"));Check(!RebirthStationRefundArchive.TryRead(extra,"owner",out _),"comment shape denied");var clone=archive.Clone().Write();clone.SetAttributeValue("job","changed");Check(archive.JobId!="changed","archive immutable copy");}
  var node=mobile.Write();node.Element("stationAdmission").SetAttributeValue("mobile","no");Check(!RebirthStationRefundArchive.TryRead(node,"owner",out _),"v2 terrain address refused");node=mobile.Write();node.Element("camperStationPublication").SetAttributeValue("unrelated","changed");Check(!RebirthStationRefundArchive.TryRead(node,"owner",out _),"full mobile queued publication bound through actual delivery codec");node=mobile.Write();node.Element("camperStationRefundDelivery").SetAttributeValue("phase","deliveryAttempted");Check(!RebirthStationRefundArchive.TryRead(node,"owner",out _),"unsaved mobile delivery cannot archive");node=mobile.Write();node.Element("stationTerminalIntent").SetAttributeValue("completion","yes");Check(!RebirthStationRefundArchive.TryRead(node,"owner",out _),"completion/cancellation conflict refused");node=mobile.Write();node.Element("camperStationCancellation").Remove();node.Add(c.Write());Check(!RebirthStationRefundArchive.TryRead(node,"owner",out _),"terrain cancellation cannot substitute into mobile payload");node=mobile.Write();node.SetAttributeValue("version",1);Check(!RebirthStationRefundArchive.TryRead(node,"owner",out _),"mobile payload cannot masquerade as v1");
  var records=new Dictionary<string,RebirthStationRefundArchive>{{terrain.JobId,terrain},{mobile.JobId,mobile}};var section=RebirthStationRefundArchive.WriteAll(records,"owner");Check((string)section.Attribute("version")=="1"&&RebirthStationRefundArchive.ReadAll(new XElement("progression",section),"owner",out var read)&&read.Count==2&&read["terrain"].DeliveryId==terrain.DeliveryId&&read["mobile"].DeliveryId==mobile.DeliveryId,"mixed versions share unchanged outer collection");
  var duplicate=Mobile("other-mobile",terrain.DeliveryId,out _);records.Add(duplicate.JobId,duplicate);try{RebirthStationRefundArchive.WriteAll(records,"owner");throw new Exception("cross-version duplicate delivery written");}catch(InvalidDataException){}section.Add(duplicate.Write());Check(!RebirthStationRefundArchive.ReadAll(new XElement("progression",section),"owner",out _),"cross-version duplicate delivery read denied");records.Remove(duplicate.JobId);
  var malformed=new XElement("stationRefundArchives",new XAttribute("version",1),mobile.Write(),mobile.Write());Check(!RebirthStationRefundArchive.ReadAll(new XElement("progression",malformed),"owner",out _),"duplicate job refused");Check(RebirthStationRefundArchive.ReadAll(new XElement("progression"),"owner",out read)&&read.Count==0,"legacy absent section preserved");
  var completionId=Guid.NewGuid();var ca=new RebirthStationGridAdmission(completionId.ToString("N"),true);var cq=new RebirthCamperStationPublicationRecord();var cc=new RebirthCamperStationCompletionRecord();var ct=new RebirthCamperStationTrainingRecord();var ci=new RebirthStationTerminalIntent();ci.Node.SetAttributeValue("completion","yes");Check(RebirthStationRefundArchive.TryCreate("owner",ca,cq,cc,ct,ci,out var complete)&&complete.IsMobile&&complete.IsCompletion&&complete.DeliveryId==completionId&&complete.Write().Elements().Count()==5,"v3 completion API and five children");Check(!terrain.IsCompletion&&!mobile.IsCompletion,"legacy versions remain refund archives");Check(RebirthStationRefundArchive.TryRead(complete.Write(),"owner",out var loadedCompletion)&&loadedCompletion.IsCompletion,"v3 read roundtrip");
  foreach(var child in complete.Write().Elements()){var bad=complete.Write();bad.Element(child.Name).SetAttributeValue("valid","no");Check(!RebirthStationRefundArchive.TryRead(bad,"owner",out _),"v3 parent validation "+child.Name);}foreach(var field in new[]{"version","owner","job","creation"}){var bad=complete.Write();bad.SetAttributeValue(field,"wrong");Check(!RebirthStationRefundArchive.TryRead(bad,"owner",out _),"v3 outer binding "+field);}var badCompletion=complete.Write();badCompletion.Element("stationTerminalIntent").SetAttributeValue("completion","no");Check(!RebirthStationRefundArchive.TryRead(badCompletion,"owner",out _),"v3 cancellation intent refused");badCompletion=complete.Write();badCompletion.Add(mobile.Write().Element("camperStationRefundDelivery"));Check(!RebirthStationRefundArchive.TryRead(badCompletion,"owner",out _),"v3 refund child forbidden");badCompletion=complete.Write();badCompletion.Element("stationAdmission").SetAttributeValue("mobile","no");Check(!RebirthStationRefundArchive.TryRead(badCompletion,"owner",out _),"v3 terrain refused");ca.JobId="not-guid";Check(!RebirthStationRefundArchive.TryCreate("owner",ca,cq,cc,ct,ci,out _),"v3 receipt job must be Guid");ca.JobId=Guid.Empty.ToString("N");Check(!RebirthStationRefundArchive.TryCreate("owner",ca,cq,cc,ct,ci,out _),"v3 empty receipt job denied");
  records.Add(complete.JobId,complete);Check(RebirthStationRefundArchive.ReadAll(new XElement("progression",RebirthStationRefundArchive.WriteAll(records,"owner")),"owner",out read)&&read.Count==3&&read[complete.JobId].IsCompletion,"v1 v2 v3 share bounded history");var collision=Mobile("refund-collision",completionId,out _);records.Add(collision.JobId,collision);try{RebirthStationRefundArchive.WriteAll(records,"owner");throw new Exception("completion/refund receipt collision written");}catch(InvalidDataException){}var collisionSection=new XElement("stationRefundArchives",new XAttribute("version",1),complete.Write(),collision.Write());Check(!RebirthStationRefundArchive.ReadAll(new XElement("progression",collisionSection),"owner",out _),"completion/refund receipt collision denied on read");records.Remove(collision.JobId);
  Console.WriteLine("PASS actual mixed refund archive codec and actual mobile delivery codec: v1 byte shape/API retained, v2 full parent/saved-phase/address validation, v3 exact five-child completion dispatch and job receipt identity, immutable copies, malformed/terrain/mobile/conflicting payload refusal and cross-version duplicate delivery IDs. Parent/native plan adapters doubled; archive parsing grants no delivery/retirement authority.");
 }
